const main=document.querySelector('main');
const home=`<section class="hero wrap"><div class="eyebrow"><span class="dash"></span> SOFTWARE HOUSE INDIPENDENTE</div><div class="hero-layout"><div class="hero-copy"><h1>Idee chiare. <br>Software <span class="accent word">concreto.</span></h1><p>Trasformiamo le idee in esperienze digitali. <br>Progressive Web App, strumenti e mondi da esplorare. <br>Progettati con cura. Sviluppati per le persone.</p><div class="actions"><a class="button" href="/progetti/">Esplora i progetti <span>↗</span></a><a class="plain-link" href="/contatti/">Hai un’idea? Parliamone <span>↗</span></a></div></div><div class="hero-art" aria-hidden="true"><div class="art-label">IDEA → DESIGN → CODE</div><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="big-h"><i></i><i></i><i></i></div><span class="art-plus plus-one">+</span><span class="art-plus plus-two">+</span><span class="code-tag">&lt; / &gt;</span><span class="art-caption">MADE OF IDEAS. BUILT WITH CODE.</span></div></div><div class="hero-bottom"><span>Dal primo pixel all’ultima riga di codice.</span><a href="#selected">SCOPRI HORUDEV <span>↓</span></a></div></section><div class="ticker"><div>PROGRESSIVE WEB APP <span>✳</span> DESIGN ESSENZIALE <span>✳</span> SVILUPPO INDIPENDENTE <span>✳</span> IDEE IN MOVIMENTO <span>✳</span></div></div><section class="section wrap" id="selected"><div class="section-head"><div><div class="eyebrow">01 / DAL NOSTRO LABORATORIO</div><h2>Le idee prendono forma.</h2></div><a class="plain-link" href="/progetti/">Tutti i progetti ↗</a></div><div class="projects-grid" id="home-projects"></div></section><section class="cta wrap"><div class="eyebrow">IL PROSSIMO PROGETTO?</div><h2>Potrebbe iniziare<br>da una tua <em>idea.</em></h2><a class="button" href="/contatti/">Costruiamola insieme ↗</a><span class="cta-star" aria-hidden="true">✳</span></section>`;
main.innerHTML=home;
const projectCards=`<article class="project-card"><a href="/progetti/#toodo" aria-label="Scopri Toodo"><div class="project-visual toodo-visual"><div class="visual-top"><span>TOODO / WEB APP</span><span>01</span></div><div class="mini-app" aria-hidden="true"><div class="mini-side"><b>toodo</b><span class="mini-active">◫ &nbsp; Panoramica</span><span>▤ &nbsp; Prenotazioni</span><span>◷ &nbsp; Attività</span><span>⚙ &nbsp; Impostazioni</span></div><div class="mini-content"><div class="mini-heading">Tutto sotto controllo.<span>＋</span></div><div class="mini-stats"><div><small>Prenotazioni</small><b>24</b></div><div><small>In programma</small><b>08</b></div></div><div class="mini-row"><i></i><span>La tua giornata, organizzata.</span><em>09:30</em></div><div class="mini-row"><i></i><span>Più spazio all’ospitalità.</span><em>10:00</em></div><div class="mini-bars"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div></div><span class="visual-caption">CONCEPT DI INTERFACCIA</span></div><div class="card-title"><h3>Toodo<span>↗</span></h3><span class="badge">Closed Alpha</span></div><p>Meno complessità. Più ospitalità. <br>Il gestionale pensato per chi accoglie, ogni giorno.</p><div class="tags"><span>PROGRESSIVE WEB APP</span><span>HOSPITALITY</span></div></a></article><article class="project-card"><a href="/progetti/#evion" aria-label="Scopri Evion"><div class="project-visual evion-visual"><div class="visual-top"><span>EVION / VIDEOGAME</span><span>02</span></div><div class="evion-type" aria-hidden="true"><span>UN ALTRO TEMPO.</span><strong>EVION</strong><span>UN MONDO DA ESPLORARE.</span></div><span class="visual-caption">NEOLITICO · ESPLORAZIONE · NATURA</span></div><div class="card-title"><h3>Evion<span>↗</span></h3><span class="badge neutral">In sviluppo</span></div><p>Un ritorno alle origini. <br>Un videogioco nella giungla rurale del Neolitico.</p><div class="tags"><span>VIDEOGAME</span><span>NUOVI MONDI</span></div></a></article>`;
const projects=`<section class="page-intro wrap"><div class="eyebrow">01 / PROGETTI</div><h1>Idee diverse. <br>La stessa <span class="accent">cura.</span></h1><p>Dagli strumenti per il lavoro ai mondi da esplorare. <br>Ecco cosa stiamo costruendo in Horudev.</p></section><section class="wrap project-list"><div class="projects-grid">${projectCards}</div><article class="project-detail" id="toodo"><div><div class="eyebrow">01 / PROGRESSIVE WEB APP</div><h2>Toodo</h2><span class="badge">Closed Alpha</span></div><div><h3>L’ospitalità ha già tante sfide. <br>Il software dovrebbe semplificarle.</h3><p>Toodo è il gestionale di Horudev dedicato a ristoranti, bar, hotel e pasticcerie. Un progetto nato per rendere più semplice l’organizzazione delle attività quotidiane, attraverso una Progressive Web App.</p><p>Attualmente in <strong>Closed Alpha</strong>: l’accesso è limitato a un gruppo di test. Scrivici per conoscere il progetto e chiedere informazioni sulla sperimentazione.</p><a class="button" href="/contatti/?progetto=Toodo">Parliamo di Toodo ↗</a></div></article><article class="project-detail" id="evion"><div><div class="eyebrow">02 / VIDEOGAME</div><h2>Evion</h2><span class="badge neutral">In sviluppo</span></div><div><h3>Prima delle città. <br>Prima del mondo che conosciamo.</h3><p>Evion è un videogioco ambientato in una giungla rurale del Neolitico. Un nuovo territorio creativo per Horudev, tra natura e un’epoca lontana.</p><p>Il progetto è in sviluppo. I dettagli e le novità saranno condivisi con l’avanzare dei lavori.</p><a class="plain-link" href="/contatti/?progetto=Evion">Chiedi informazioni su Evion ↗</a></div></article></section>`;
const store=`<section class="page-intro wrap"><div class="eyebrow">02 / STORE</div><h1>Piccoli asset. <br>Nuove <span class="accent">possibilità.</span></h1><p>Risorse per chi ama creare. <br>Una parte del nostro laboratorio, a disposizione del tuo.</p></section><section class="wrap store-section"><div class="store-art" aria-hidden="true"><span class="eyebrow">HORUDEV / DEVELOPER ASSETS</span><div class="asset-symbol">{<span>✳</span>}</div><div class="asset-bottom"><span>MADE FOR BUILDERS</span><span>↗</span></div></div><div class="store-copy"><span class="badge">SU GUMROAD</span><h2>Una risorsa in più<br>per la tua prossima idea.</h2><p>Nel piccolo store Gumroad di Horudev trovi asset per sviluppatori: risorse da acquistare e contenuti da scaricare gratuitamente.</p><p>Scopri i materiali disponibili e scegli quelli adatti al tuo progetto. Le condizioni di utilizzo sono indicate nella pagina di ciascun asset.</p><a class="button" id="store-link" href="mailto:horudev@gmail.com?subject=Informazioni%20sullo%20store%20Gumroad">Richiedi il link allo store ↗</a><p class="form-note">Scrivici per ricevere il collegamento al catalogo Gumroad.</p></div></section>`;
const contacts=`<section class="page-intro wrap"><div class="eyebrow">03 / CONTATTI</div><h1>Le cose belle iniziano<br>con un <span class="accent">ciao.</span></h1><p>Un’idea da sviluppare, una domanda o una curiosità?<br>Ci fa piacere sentirti.</p></section><section class="wrap contact-grid"><div class="contact-copy"><span class="eyebrow">SCRIVICI DIRETTAMENTE</span><a class="email-link" href="mailto:horudev@gmail.com">horudev@gmail.com ↗</a><p>Raccontaci cosa hai in mente. <br>Partiamo da lì.</p><div class="newsletter"><span class="newsletter-star" aria-hidden="true">✳</span><h3>Ci sono idee in arrivo.</h3><p>Richiedi via email di ricevere novità su progetti, sviluppi e nuove risorse.</p><form id="newsletter-form"><label for="newsletter-email">La tua email</label><div class="newsletter-input"><input id="newsletter-email" name="email" type="email" autocomplete="email" placeholder="nome@esempio.it" required maxlength="254"><button aria-label="Prepara la richiesta newsletter" type="submit">↗</button></div><label class="check"><input type="checkbox" required><span>Ho letto la <a href="/termini/#privacy">privacy</a> e richiedo aggiornamenti via email.</span></label><p class="form-note">Si aprirà il tuo programma email: invia la richiesta per contattarci.</p><p class="form-status" role="status"></p></form></div></div><form id="contact-form" class="contact-form"><div class="form-row"><div><label for="name">Il tuo nome</label><input id="name" name="name" autocomplete="name" required placeholder="Come ti chiami?" maxlength="100"></div><div><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email" required placeholder="nome@esempio.it" maxlength="254"></div></div><label for="subject">Di cosa parliamo?</label><input id="subject" name="subject" placeholder="Un nuovo progetto, Toodo, Evion…" required maxlength="150"><label for="message">Il tuo messaggio</label><textarea id="message" name="message" rows="5" placeholder="Raccontaci la tua idea…" required minlength="10" maxlength="4000"></textarea><label class="check"><input type="checkbox" required><span>Ho letto l’<a href="/termini/#privacy">informativa privacy</a>.</span></label><button class="button" type="submit">Prepara il messaggio <span>↗</span></button><p class="form-note">Il modulo apre un’email compilata. L’invio avviene dal tuo programma di posta.</p><p class="form-status" role="status"></p></form></section>`;
const legal=`<section class="page-intro wrap"><div class="eyebrow">INFORMAZIONI SUL SITO</div><h1>Termini <span class="accent">e privacy.</span></h1><p>Informazioni sull’utilizzo di questa versione del sito.</p></section><section class="wrap legal"><h2>Utilizzo del sito</h2><p>Questo sito presenta Horudev e i suoi progetti. Toodo è in Closed Alpha ed Evion è in sviluppo: la presenza sul sito non implica disponibilità pubblica, date di rilascio o accesso garantito. Per informazioni puoi scrivere a <a href="mailto:horudev@gmail.com">horudev@gmail.com</a>.</p><h2>Asset e store</h2><p>Gli asset sono distribuiti tramite Gumroad. Prezzi, licenze e condizioni di acquisto o download sono quelli indicati sulle singole pagine del prodotto e sulla piattaforma al momento dell’acquisto.</p><h2 id="privacy">Dati e contatti</h2><p>I moduli di questa versione non trasmettono né archiviano i dati su un server Horudev. Preparano un messaggio nel programma di posta del visitatore, che può modificarlo e scegliere se inviarlo a horudev@gmail.com. L’indirizzo e il contenuto saranno ricevuti da Horudev solo dopo l’invio tramite il servizio email scelto.</p><p>La richiesta newsletter è una richiesta via email, non un’iscrizione automatica. Per informazioni sui tuoi messaggi o per chiedere di non ricevere ulteriori aggiornamenti, scrivi allo stesso indirizzo.</p><h2 id="cookie">Cookie e preferenze</h2><p>Il sito non integra strumenti pubblicitari o di analisi. Utilizza la memoria locale del browser per ricordare il tema selezionato e la scelta nel banner. “Solo necessari” e “Accetta” chiudono il banner senza attivare tracciamenti aggiuntivi. Puoi riaprire il banner dal collegamento Cookie nel footer o cancellare queste preferenze dai dati del browser.</p><h2>Informazioni da completare</h2><p>Prima del lancio pubblico, questa pagina deve essere completata con i dati del titolare, le informazioni sul servizio di hosting e le condizioni degli eventuali servizi di contatto e newsletter che saranno attivati.</p></section>`;
const page=location.pathname.split('/').filter(Boolean)[0]||'home';
const pages={home,progetti:projects,store,contatti:contacts,termini:legal};
main.innerHTML=pages[page]||home;
if(page==='home')document.querySelector('#home-projects').innerHTML=projectCards;
document.querySelector(`[data-page="${page}"]`)?.setAttribute('aria-current','page');
document.title=({home:'Idee chiare. Software concreto.',progetti:'Progetti',store:'Store',contatti:'Contatti',termini:'Termini e privacy'}[page]||'Home')+' — Horudev';
document.querySelector('#year').textContent=new Date().getFullYear();
function readPreference(key){try{return localStorage.getItem(key)}catch{return null}}
function writePreference(key,value){try{localStorage.setItem(key,value)}catch{}}
const themeButton=document.querySelector('.theme-button');
function setTheme(theme){document.documentElement.dataset.theme=theme;themeButton.textContent=theme==='dark'?'☼':'☾';themeButton.setAttribute('aria-label',theme==='dark'?'Attiva tema chiaro':'Attiva tema scuro');themeButton.setAttribute('aria-pressed',String(theme==='light'))}
setTheme(readPreference('horudev-theme')==='light'?'light':'dark');
themeButton.addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';setTheme(theme);writePreference('horudev-theme',theme)});
const cookie=document.querySelector('.cookie');cookie.hidden=!!readPreference('horudev-cookie-choice');
document.querySelectorAll('[data-consent]').forEach(button=>button.addEventListener('click',()=>{writePreference('horudev-cookie-choice',button.dataset.consent);cookie.hidden=true}));
document.querySelector('#cookie-reopen').addEventListener('click',()=>{cookie.hidden=false;cookie.querySelector('button').focus()});
const contactForm=document.querySelector('#contact-form');
if(contactForm){document.querySelector('#subject').value=new URLSearchParams(location.search).get('progetto')||'';contactForm.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(contactForm);const body=`Nome: ${data.get('name')}\nEmail: ${data.get('email')}\n\n${data.get('message')}`;location.href=`mailto:horudev@gmail.com?subject=${encodeURIComponent(data.get('subject'))}&body=${encodeURIComponent(body)}`;contactForm.querySelector('.form-status').textContent='Email preparata. Completa l’invio nel programma di posta. Se non si apre, scrivi direttamente a horudev@gmail.com.'})}
const newsletterForm=document.querySelector('#newsletter-form');
newsletterForm?.addEventListener('submit',event=>{event.preventDefault();const email=new FormData(newsletterForm).get('email');location.href=`mailto:horudev@gmail.com?subject=${encodeURIComponent('Richiesta aggiornamenti Horudev')}&body=${encodeURIComponent('Ciao Horudev, vorrei ricevere aggiornamenti sui vostri progetti e risorse a questo indirizzo: '+email+'. Ho letto le informazioni privacy. Grazie!')}`;newsletterForm.querySelector('.form-status').textContent='Richiesta preparata: inviala dal tuo programma di posta. Non sei ancora iscritto automaticamente.'});
if(location.hash)requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView());


